8	        // get facet from function selector
9	        address facet = ds.selectorToFacetAndPosition[msg.sig].facetAddress;
10	        require(facet != address(0), "Diamond: Function does not exist");
11	        // Execute external function from facet using delegatecall and return any value.
12	        assembly {
13	            // copy function selector and any arguments
14	            calldatacopy(0, 0, calldatasize())
15	            // execute function call using the facet
16	            let result := delegatecall(gas(), facet, 0, calldatasize(), 0, 0)
17	            // get any return value
18	            returndatacopy(0, 0, returndatasize())
19	            // return any return value or error back to the caller
20	            switch result
21	            case 0 {
22	                revert(0, returndatasize())
23	            }
24	            default {
25	                return(0, returndatasize())
26	            }
27	        }
28	    }

