1	function deposit(uint256 assets, address receiver)
2	        public
3	        override
4	        nonReentrant
5	        onlyDiamond
6	        notPaused
7	        addressZeroCheck(receiver)
8	        validAmount(assets)
9	        returns (uint256 shares)
10	    {
11	        // accrue interest up to now (non-compounding)
12	        _accrueInterest();
13	
14	        // Snapshot the pre-transfer share supply and asset base. Shares must be
15	        // minted from the amount the vault ACTUALLY receives, not the nominal
16	        // `assets`: a fee-on-transfer token delivers less on this second hop, so
17	        // minting `previewDeposit(assets)` over-mints shares against real assets
18	        // (#5). Computing shares against the pre-transfer snapshot keeps the
19	        // ERC4626 exchange rate exact (matches OZ `_convertToShares`, offset 0).
20	        uint256 _supply = totalSupply();
21	        uint256 _assetsBefore = totalAssets();
22	
23	        // Transfer assets from sender to this vault
24	        uint256 _balBefore = IERC20(asset()).balanceOf(address(this));
25	        IERC20(asset()).safeTransferFrom(msg.sender, address(this), assets);
26	        uint256 _received = IERC20(asset()).balanceOf(address(this)) - _balBefore;
27	        if (_received == 0) revert InvalidAmount();
28	
29	        shares = Math.mulDiv(_received, _supply + 1, _assetsBefore + 1);
30	        if (shares == 0) revert InvalidAmount();
31	
32	        // Mint shares to receiver
33	        _mint(receiver, shares);
34	
35	        emit Deposit(msg.sender, receiver, _received, shares);
36	        return shares;
37	    }

1	function withdraw(uint256 assets, address receiver, address owner)
2	        public
3	        override
4	        nonReentrant
5	        onlyDiamond
6	        addressZeroCheck(receiver)
7	        addressZeroCheck(owner)
8	        validAmount(assets)
9	        returns (uint256 shares)
10	    {
11	        // accrue interest up to now (non-compounding)
12	        _accrueInterest();
13	
14	        // Calculate shares needed
15	        shares = previewWithdraw(assets);
16	        if (shares == 0) revert InvalidAmount();
17	
18	        // Check if owner has enough shares
19	        if (balanceOf(owner) < shares) revert InsufficientShares();
20	
21	        // Check allowance if a third party is spending the owner's shares. The
22	        // diamond is exempt: `withdraw` is `onlyDiamond`, and the diamond's
23	        // `_withdraw` already pins `owner` to the calling depositor, so it never
24	        // moves another user's shares — a separate user→diamond share approval
25	        // would otherwise be required and the deposit flow never grants it (#7).
26	        if (msg.sender != owner && msg.sender != diamond) {
27	            _spendAllowance(owner, msg.sender, shares);
28	        }
29	
30	        // only the non-reserve liquid balance is withdrawable by LPs
31	        uint256 _balance = IERC20(asset()).balanceOf(address(this));
32	        if (_balance - totalProtocolReserve < assets) {
33	            revert InsufficientBalance();
34	        }
35	
36	        // Burn shares first
37	        _burn(owner, shares);
38	
39	        // Transfer assets to receiver
40	        IERC20(asset()).safeTransfer(receiver, assets);
41	
42	        emit Withdraw(msg.sender, receiver, owner, assets, shares);
43	        return shares;
44	    }

