1	function _doRepay(uint256 principalRepaid, uint256 interestPaid, uint16 fixedRate) internal {
2	        _accrueInterest();
3	
4	        if (principalRepaid >= totalBorrows) {
5	            totalBorrows = 0;
6	        } else {
7	            totalBorrows = totalBorrows - principalRepaid;
8	        }
9	
10	        if (fixedRate != 0) {
11	            uint256 _productReduction = principalRepaid * fixedRate;
12	            if (principalRepaid >= fixedBorrows) {
13	                fixedBorrows = 0;
14	                fixedRateProduct = 0;
15	            } else {
16	                fixedBorrows = fixedBorrows - principalRepaid;
17	                fixedRateProduct =
18	                    _productReduction >= fixedRateProduct ? 0 : fixedRateProduct - _productReduction;
19	            }
20	        }
21	
22	        uint256 _reserve = (interestPaid * reserveFactor) / Constants.BASIS_POINTS_SCALE_256;
23	        uint256 _lpInterest = interestPaid - _reserve;
24	
25	        {
26	            // Both floating and fixed interest are accrued smoothly as a receivable
27	            // (fixed via `fixedRateProduct`), so realizing a repayment as cash means
28	            // removing the receivable to keep `totalAssets` continuous.
29	            if (_lpInterest >= totalAccruedInterest) {
30	                totalAccruedInterest = 0;
31	            } else {
32	                totalAccruedInterest = totalAccruedInterest - _lpInterest;
33	            }
34	        }
35	        totalProtocolReserve = totalProtocolReserve + _reserve;
36	
37	        emit Repay(_msgSender(), principalRepaid + interestPaid);
38	    }

