1	function updateBadDebt(uint256 amount) external onlyDiamond validAmount(amount) {
2	        // accrue interest before updating bad debt
3	        _accrueInterest();
4	
5	        uint256 _totalBorrowedWithInterest = totalBorrows + totalAccruedInterest;
6	
7	        // Validate bad debt amount doesn't exceed total borrowed amount + accrued interest
8	        if (amount > _totalBorrowedWithInterest) {
9	            revert InvalidAmount();
10	        }
11	
12	        // increase bad debt (reduces totalAssets)
13	        totalBadDebt = totalBadDebt + amount;
14	
15	        // Write off bad debt: first from principal, then from accrued interest
16	        uint256 _remainingBadDebt = amount;
17	
18	        if (_remainingBadDebt >= totalBorrows) {
19	            // Write off entire principal
20	            _remainingBadDebt = _remainingBadDebt - totalBorrows;
21	            totalBorrows = 0;
22	        } else {
23	            // Partial write-off from principal
24	            totalBorrows = totalBorrows - _remainingBadDebt;
25	            _remainingBadDebt = 0;
26	        }
27	        // Keep the invariant fixedBorrows <= totalBorrows after writing off
28	        // principal (the written-off debt may have been a fixed loan). Scale the
29	        // rate product down in proportion so the blended fixed rate is preserved.
30	        if (fixedBorrows > totalBorrows) {
31	            uint256 _newFixed = totalBorrows;
32	            fixedRateProduct = fixedBorrows == 0 ? 0 : (fixedRateProduct * _newFixed) / fixedBorrows;
33	            fixedBorrows = _newFixed;
34	        }
35	
36	        // Write off remaining bad debt from accrued interest
37	        if (_remainingBadDebt > 0) {
38	            if (_remainingBadDebt >= totalAccruedInterest) {
39	                totalAccruedInterest = 0;
40	            } else {
41	                totalAccruedInterest = totalAccruedInterest - _remainingBadDebt;
42	            }
43	        }
44	
45	        emit BadDebtUpdated(amount, totalBadDebt);
46	    }

1	function _accrueInterest() internal {
2	        uint256 timeElapsed = block.timestamp - lastUpdateTimestamp;
3	        if (timeElapsed == 0) return;
4	
5	        uint256 lpInterest = _pendingInterest();
6	        if (lpInterest > 0) {
