8	        }
9	
10	        lastUpdateTimestamp = block.timestamp;
11	    }

1	function _pendingInterest() internal view returns (uint256) {
2	        uint256 _timeElapsed = block.timestamp - lastUpdateTimestamp;
3	        // Floating (pooled) principal accrues at the mutable vault rate; fixed
4	        // principal accrues at its own snapshotted blended rate (`fixedRateProduct`
5	        // = Σ principal·rate). Keeping fixed accrual off the mutable rate is what
6	        // stops a governance rate change from minting phantom interest on fixed
7	        // loans that early LPs could extract (#9). When the rate is unchanged the
8	        // two formulas coincide, so accrual stays identical to the single-rate case.
9	        // Defensive: never underflow if the fixed/total buckets momentarily
10	        // diverge — `totalAssets()` depends on this view and must never revert.
11	        uint256 _floatingBorrows = totalBorrows > fixedBorrows ? totalBorrows - fixedBorrows : 0;
12	        uint256 _rateProduct = (_floatingBorrows * interestRate) + fixedRateProduct;
13	        uint256 _gross = (_rateProduct * _timeElapsed) / (Constants.BASIS_POINTS_SCALE_256 * Constants.ONE_YEAR);
14	        return (_gross * (Constants.BASIS_POINTS_SCALE_256 - reserveFactor)) / Constants.BASIS_POINTS_SCALE_256;
15	    }

