1	function diamondCut(IDiamondCut.FacetCut[] memory _diamondCut, address _init, bytes memory _calldata) internal {
2	        for (uint256 facetIndex; facetIndex < _diamondCut.length; facetIndex++) {
3	            IDiamondCut.FacetCutAction action = _diamondCut[facetIndex].action;
4	            if (action == IDiamondCut.FacetCutAction.Add) {
5	                addFunctions(_diamondCut[facetIndex].facetAddress, _diamondCut[facetIndex].functionSelectors);
6	            } else if (action == IDiamondCut.FacetCutAction.Replace) {
7	                replaceFunctions(_diamondCut[facetIndex].facetAddress, _diamondCut[facetIndex].functionSelectors);
8	            } else if (action == IDiamondCut.FacetCutAction.Remove) {
9	                removeFunctions(_diamondCut[facetIndex].facetAddress, _diamondCut[facetIndex].functionSelectors);
10	            } else {
11	                revert InValidFacetCutAction();
12	            }
13	        }
14	        emit DiamondCut(_diamondCut, _init, _calldata);
15	        initializeDiamondCut(_init, _calldata);
16	    }

1	function addFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
2	        if (_functionSelectors.length <= 0) revert NoSelectorsInFacet();
3	        DiamondStorage storage ds = diamondStorage();
4	        if (_facetAddress == address(0)) revert NoZeroAddress();
5	        uint96 selectorPosition = uint96(ds.facetFunctionSelectors[_facetAddress].functionSelectors.length);
6	        // add new facet address if it does not exist
7	        if (selectorPosition == 0) {
8	            addFacet(ds, _facetAddress);
9	        }
10	        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
11	            bytes4 selector = _functionSelectors[selectorIndex];
12	            address oldFacetAddress = ds.selectorToFacetAndPosition[selector].facetAddress;
13	            if (oldFacetAddress != address(0)) revert SelectorExists(selector);
14	            addFunction(ds, selector, selectorPosition, _facetAddress);
15	            selectorPosition++;
16	        }
17	    }

1	function replaceFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
2	        if (_functionSelectors.length <= 0) revert NoSelectorsInFacet();
3	        DiamondStorage storage ds = diamondStorage();
4	        if (_facetAddress == address(0)) revert NoZeroAddress();
5	        uint96 selectorPosition = uint96(ds.facetFunctionSelectors[_facetAddress].functionSelectors.length);
6	        // add new facet address if it does not exist
7	        if (selectorPosition == 0) {
8	            addFacet(ds, _facetAddress);
9	        }
10	        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
11	            bytes4 selector = _functionSelectors[selectorIndex];
12	            address oldFacetAddress = ds.selectorToFacetAndPosition[selector].facetAddress;
13	            if (oldFacetAddress == _facetAddress) {
14	                revert SameSelectorReplacement(selector);
15	            }
16	            removeFunction(ds, oldFacetAddress, selector);
17	            addFunction(ds, selector, selectorPosition, _facetAddress);
18	            selectorPosition++;
19	        }
20	    }

1	function removeFunctions(address _facetAddress, bytes4[] memory _functionSelectors) internal {
2	        if (_functionSelectors.length <= 0) revert NoSelectorsInFacet();
3	        DiamondStorage storage ds = diamondStorage();
4	        // if function does not exist then do nothing and return
5	        if (_facetAddress != address(0)) revert MustBeZeroAddress();
6	        for (uint256 selectorIndex; selectorIndex < _functionSelectors.length; selectorIndex++) {
7	            bytes4 selector = _functionSelectors[selectorIndex];
8	            address oldFacetAddress = ds.selectorToFacetAndPosition[selector].facetAddress;
9	            removeFunction(ds, oldFacetAddress, selector);
10	        }
11	    }

1	function addFacet(DiamondStorage storage ds, address _facetAddress) internal {
2	        enforceHasContractCode(_facetAddress);
3	        ds.facetFunctionSelectors[_facetAddress].facetAddressPosition = ds.facetAddresses.length;
4	        ds.facetAddresses.push(_facetAddress);
5	    }

1	function addFunction(DiamondStorage storage ds, bytes4 _selector, uint96 _selectorPosition, address _facetAddress)
2	        internal
3	    {
4	        ds.selectorToFacetAndPosition[_selector].functionSelectorPosition = _selectorPosition;
5	        ds.facetFunctionSelectors[_facetAddress].functionSelectors.push(_selector);
6	        ds.selectorToFacetAndPosition[_selector].facetAddress = _facetAddress;
7	    }

1	function removeFunction(DiamondStorage storage ds, address _facetAddress, bytes4 _selector) internal {
2	        if (_facetAddress == address(0)) revert NonExistentSelector(_selector);
3	        // an immutable function is a function defined directly in a diamond
4	        if (_facetAddress == address(this)) revert ImmutableFunction(_selector);
5	        // replace selector with last selector, then delete last selector
6	        uint256 selectorPosition = ds.selectorToFacetAndPosition[_selector].functionSelectorPosition;
7	        uint256 lastSelectorPosition = ds.facetFunctionSelectors[_facetAddress].functionSelectors.length - 1;
8	        // if not the same then replace _selector with lastSelector
9	        if (selectorPosition != lastSelectorPosition) {
10	            bytes4 lastSelector = ds.facetFunctionSelectors[_facetAddress].functionSelectors[lastSelectorPosition];
11	            ds.facetFunctionSelectors[_facetAddress].functionSelectors[selectorPosition] = lastSelector;
12	            // selectorPosition is an index into a function-selector array; it cannot
13	            // approach 2^96, so the uint96 cast cannot truncate.
14	            // forge-lint: disable-next-line(unsafe-typecast)
15	            ds.selectorToFacetAndPosition[lastSelector].functionSelectorPosition = uint96(selectorPosition);
16	        }
17	        // delete the last selector
18	        ds.facetFunctionSelectors[_facetAddress].functionSelectors.pop();
19	        delete ds.selectorToFacetAndPosition[_selector];
20	
21	        // if no more selectors for facet address then delete the facet address
22	        if (lastSelectorPosition == 0) {
23	            // replace facet address with last facet address and delete last facet address
24	            uint256 lastFacetAddressPosition = ds.facetAddresses.length - 1;
25	            uint256 facetAddressPosition = ds.facetFunctionSelectors[_facetAddress].facetAddressPosition;
26	            if (facetAddressPosition != lastFacetAddressPosition) {
27	                address lastFacetAddress = ds.facetAddresses[lastFacetAddressPosition];
28	                ds.facetAddresses[facetAddressPosition] = lastFacetAddress;
29	                ds.facetFunctionSelectors[lastFacetAddress].facetAddressPosition = facetAddressPosition;
30	            }
31	            ds.facetAddresses.pop();
32	            delete ds.facetFunctionSelectors[_facetAddress].facetAddressPosition;
33	        }
34	    }

1	function initializeDiamondCut(address _init, bytes memory _calldata) internal {
2	        if (_init == address(0)) {
3	            if (_calldata.length > 0) revert NonEmptyCalldata();
4	        } else {
5	            if (_calldata.length == 0) revert EmptyCalldata();
6	            if (_init != address(this)) {
7	                enforceHasContractCode(_init);
8	            }
9	            (bool success, bytes memory error) = _init.delegatecall(_calldata);
10	            if (!success) {
11	                if (error.length > 0) {
12	                    // bubble up the error
13	                    revert(string(error));
14	                } else {
15	                    revert InitCallFailed();
16	                }
17	            }
18	        }
19	    }

