1	function _liquidateLoan(
2	        LibAppStorage.StorageLayout storage s,
3	        uint256 _loanId,
4	        uint256 _amount,
5	        address _collateralToken
6	    ) internal {
7	        Loan storage _loan = s.s_loans[_loanId];
8	        if (_loan.status != LoanStatus.FULFILLED) revert INACTIVE_LOAN();
9	        _liquidationCheck(s, _loan.positionId, _loan.token, _collateralToken, _amount);
10	
11	        // Clamp the requested repayment to the loan's total outstanding balance.
12	        uint256 _loanDebt = s._outstandingBalance(_loanId, block.timestamp);
13	
14	        if (_amount > _loanDebt) {
15	            _amount = _loanDebt;
16	        }
17	
18	        uint256 _collateralHeld = s.s_positionCollateral[_loan.positionId][_collateralToken];
19	        uint256 _amountToLiquidate = _getAmountToLiquidate(s, _collateralToken, _loan.token, _amount);
20	
21	        // Cap the seizure to the collateral actually available instead of
22	        // reverting. A deeply-overdue loan can accrue penalty whose bonus-adjusted
23	        // seizure exceeds the remaining collateral; reverting there left the loan
24	        // permanently un-liquidatable, so its principal became bad debt (#4a).
25	        // Scale the repayment down proportionally so it only pays for the
26	        // collateral that can actually be seized.
27	        if (_amountToLiquidate > _collateralHeld) {
28	            _amount = (_amount * _collateralHeld) / _amountToLiquidate;
29	            _amountToLiquidate = _collateralHeld;
30	        }
31	
32	        uint256 _oldPrincipal = _loan.principal;
33	
34	        // Pro-rata allocation across principal and interest/penalty. Every
35	        // liquidation retires a positive slice of principal, so a liquidator can
36	        // no longer repeatedly seize collateral as interest-only while principal
37	        // (and its regenerating penalty) survives (#4b). Interest is never folded
38	        // into principal (#12): `_loan.principal` only ever decreases here.
39	        uint256 _principalRepaid = (_amount * _oldPrincipal) / _loanDebt;
40	        // A liquidation must make real progress on principal. A dust repayment
41	        // whose principal slice rounds to zero would reset `startTimestamp` (the
42	        // interest anchor) while repaying nothing — the wiped-interest footgun the
43	        // old interest floor guarded against (#3). Reject it.
44	        if (_principalRepaid == 0) revert AMOUNT_ZERO();
45	
46	        s.s_positionCollateral[_loan.positionId][_collateralToken] -= _amountToLiquidate;
47	        s.s_totalCollateralDeposited[_collateralToken] -= _amountToLiquidate;
48	        LibYieldStrategy._rebalanceForWithdrawal(s, _loan.positionId, _collateralToken, _amountToLiquidate);
49	
50	        // update outstanding loan here
51	        _loan.repaid += _amount;
52	        _loan.principal = _oldPrincipal - _principalRepaid;
53	        _loan.startTimestamp = block.timestamp;
54	
55	        // If fully repaid, update loan status and move to closed loans
56	        if (_loan.principal == 0) {
57	            _loan.status = LoanStatus.LIQUIDATED;
58	            s._removeLoanFromActive(_loan.positionId, _loanId);
59	            s.s_positionClosedLoanIds[_loan.positionId].push(_loanId);
60	        }
61	
62	        LibVaultManager._updateVaultRepays(s, _loan.token, _principalRepaid);
63	
64	        TokenVault _tokenVault = s.i_tokenVault[_loan.token];
65	
66	        // Book against the amount actually received (fee-on-transfer safe, #6).
67	        uint256 _before = IERC20(_loan.token).balanceOf(address(_tokenVault));
68	        IERC20(_loan.token).safeTransferFrom(msg.sender, address(_tokenVault), _amount);
69	        uint256 _received = IERC20(_loan.token).balanceOf(address(_tokenVault)) - _before;
70	        if (_received != _amount) revert AMOUNT_MISMATCH(_received, _amount);
71	        _tokenVault.repayFixed(_principalRepaid, _amount - _principalRepaid, _loan.annualRateBps);
72	
73	        LibProtocol._transferToken(_collateralToken, msg.sender, _amountToLiquidate);
74	
75	        emit LoanLiquidated(_loan.positionId, _loanId, _collateralToken, msg.sender, _amountToLiquidate);
76	        emit LoanRepayment(_loan.positionId, _loanId, _loan.token, _amount);
77	    }

1	function _liquidatePosition(
2	        LibAppStorage.StorageLayout storage s,
3	        uint256 _positionId,
4	        uint256 _amount,
5	        address _token,
6	        address _collateralToken
7	    ) internal {
8	        if (s.s_positionBorrowed[_positionId][_token] == 0) {
9	            revert NO_ACTIVE_BORROW_FOR_TOKEN(_positionId, _token);
10	        }
11	        _liquidationCheck(s, _positionId, _token, _collateralToken, _amount);
12	
13	        uint256 _amountToLiquidate = _getAmountToLiquidate(s, _collateralToken, _token, _amount);
14	        if (_amountToLiquidate > s.s_positionCollateral[_positionId][_collateralToken]) {
15	            revert INSUFFICIENT_COLLATERAL();
16	        }
17	
18	        s.s_positionCollateral[_positionId][_collateralToken] -= _amountToLiquidate;
19	        s.s_totalCollateralDeposited[_collateralToken] -= _amountToLiquidate;
20	        LibYieldStrategy._rebalanceForWithdrawal(s, _positionId, _collateralToken, _amountToLiquidate);
21	
22	        RepayStateChangeParams memory _params =
23	            RepayStateChangeParams({positionId: _positionId, token: _token, amount: _amount});
24	        uint256 _principalRepaid = s._repayStateChanges(_params);
25	
26	        TokenVault _tokenVault = s.i_tokenVault[_token];
27	        // Book against the amount actually received (fee-on-transfer safe, #6).
28	        uint256 _before = IERC20(_token).balanceOf(address(_tokenVault));
29	        IERC20(_token).safeTransferFrom(msg.sender, address(_tokenVault), _amount);
30	        uint256 _received = IERC20(_token).balanceOf(address(_tokenVault)) - _before;
31	        if (_received != _amount) revert AMOUNT_MISMATCH(_received, _amount);
32	        _tokenVault.repay(_principalRepaid, _amount - _principalRepaid);
33	
34	        LibProtocol._transferToken(_collateralToken, msg.sender, _amountToLiquidate);
35	
36	        emit PositionLiquidated(_positionId, msg.sender, _collateralToken, _amountToLiquidate);
37	        emit Repay(_positionId, _token, _amount);
38	    }

