7	        (, uint256 _collateralPricePerToken) = s._getPriceData(_collateralToken);
8	        if (_collateralPricePerToken == 0) revert ZERO_PRICE_DATA();
9	
10	        (, uint256 _amountValue) = s._getTokenValueInUSD(_token, _amount);
11	
12	        uint8 _pricefeedDecimals = s._getPriceDecimals(_collateralToken);
