1	function _getPriceData(LibAppStorage.StorageLayout storage s, address _token)
2	        internal
3	        view
4	        returns (bool, uint256)
5	    {
6	        address _pricefeed = s.s_tokenPriceFeed[_token];
7	        if (_pricefeed == address(0)) revert TOKEN_NOT_SUPPORTED(_token);
8	
9	        (uint80 _roundId, int256 _answer,, uint256 _updatedAt, uint80 _answeredInRound) =
10	            AggregatorV3Interface(_pricefeed).latestRoundData();
11	
12	        if (_answer <= 0) revert INVALID_PRICE_FEED(_pricefeed);
13	
14	        if (_roundId != _answeredInRound) revert STALE_PRICE_FEED(_pricefeed);
15	
16	        uint32 _threshold = s.s_priceFeedStalenessThreshold[_token];
17	        if (_threshold == 0) _threshold = Constants.DEFAULT_STALENESS_THRESHOLD;
18	        if (block.timestamp - _updatedAt > _threshold) revert STALE_PRICE_FEED(_pricefeed);
19	
20	        // `_answer` is guarded `> 0` above, so the int256->uint256 cast cannot truncate.
21	        // forge-lint: disable-next-line(unsafe-typecast)
22	        return (false, uint256(_answer));
23	    }

