1	function _getTokenValueInUSD(LibAppStorage.StorageLayout storage s, address _token, uint256 _amount)
2	        internal
3	        view
4	        returns (uint256, uint256)
5	    {
6	        if (_amount == 0) return (0, 0);
7	
8	        (bool _isStale, uint256 _price) = _getPriceData(s, _token);
9	        if (_isStale) revert STALE_PRICE_FEED(_token);
10	        if (_price <= 0) revert INVALID_PRICE_FEED(_token);
11	
12	        // Normalize to 18 decimals
13	        uint8 _decimals = LibUtils._getTokenDecimals(_token);
14	        uint8 _feedDecimals = _getPriceDecimals(s, _token);
15	        uint256 _usdValue = _calculateTokenUSDEquivalent(_decimals, _feedDecimals, _price, _amount);
16	
17	        return (_price, _usdValue);
18	    }

1	function _calculateTokenUSDEquivalent(uint8 _decimals, uint8 _feedDecimals, uint256 _price, uint256 _amount)
2	        internal
3	        pure
4	        returns (uint256 _usdValue)
5	    {
6	        if (_amount == 0) return _usdValue;
7	
8	        // Scale the feed price up from its native decimals to PRECISION_SCALE (18)
9	        uint256 scaledPrice = _price * (10 ** (Constants.PRECISION_SCALE - _feedDecimals));
10	        _usdValue = (scaledPrice * _amount) / (10 ** _decimals);
11	    }

