1	function _requestBorrow(
2	        LibAppStorage.StorageLayout storage s,
3	        BorrowRequest calldata _request,
4	        bytes calldata _signature
5	    ) internal returns (uint256) {
6	        if (bytes(_request.action).length == 0) revert EMPTY_STRING();
7	        if (_request.wallet == address(0) || _request.contractAddress == address(0)) revert ADDRESS_ZERO();
8	        if (_request.amount == 0) revert AMOUNT_ZERO();
9	        if (!s.s_supportedToken[_request.token]) revert TOKEN_NOT_SUPPORTED(_request.token);
10	
11	        uint256 _storedPositionId = s._getPositionIdForUser(_request.wallet);
12	        if (_storedPositionId == 0) revert NO_POSITION_ID(_request.wallet);
13	
14	        if (_storedPositionId != _request.positionId) {
15	            revert POSITION_ID_MISMATCH(_storedPositionId, _request.positionId);
16	        }
17	
18	        // Honour an on-chain blacklist even for a pre-signed request: a wallet
19	        // removed from the whitelist after its request was signed can no longer
20	        // draw vault funds (defence-in-depth, mirrors the local borrow path's
21	        // `_callerWhitelisted`). See finding #6.
22	        if (!s.isWhitelisted[_request.wallet]) revert ADDRESS_NOT_WHITELISTED(_request.wallet);
23	
24	        if (_request.targetChainId != block.chainid) {
25	            revert REQUEST_BORROW_TARGET_CHAIN_MISMATCH(block.chainid, _request.targetChainId);
26	        }
27	        if (_request.contractAddress != address(this)) {
28	            revert REQUEST_BORROW_CONTRACT_MISMATCH(address(this), _request.contractAddress);
29	        }
30	
31	        // Optional signature expiry: a zero deadline means no expiry; a non-zero
32	        // deadline bounds how long a spoke-chain-attested request stays valid on the hub.
33	        if (_request.deadline != 0 && block.timestamp > _request.deadline) {
34	            revert REQUEST_BORROW_EXPIRED(_request.deadline, block.timestamp);
35	        }
36	
37	        // Enforce the same minimum tenure as `_takeLoan`. (No hub-side health check
38	        // here by design: cross-chain borrows are backed by spoke-chain collateral
39	        // attested by the trusted signer, so the hub holds no collateral to measure
40	        // — a hub health check would revert every legitimate request. See
41	        // KNOWN_ISSUES.md §2.)
42	        if (_request.tenureSeconds < Constants.ONE_DAY) revert TENURE_TOO_SHORT();
43	
44	        if (!s._validateVaultUtlization(_request.token, _request.amount)) revert TOKEN_OVERUTILIZATION();
45	
46	        _verifyBorrowSignature(s, _request, _signature);
47	
48	        if (s.s_requestBorrowNonceUsed[_request.contractAddress][_request.nonce]) {
49	            revert REQUEST_BORROW_NONCE_USED(_request.wallet, _request.nonce);
50	        }
51	        s.s_requestBorrowNonceUsed[_request.contractAddress][_request.nonce] = true;
52	
53	        Loan memory _loan = Loan({
54	            positionId: _request.positionId,
55	            token: _request.token,
56	            principal: _request.amount,
57	            repaid: 0,
58	            tenureSeconds: _request.tenureSeconds,
59	            startTimestamp: block.timestamp,
60	            annualRateBps: s.s_interestRate,
61	            penaltyRateBps: s.s_penaltyRate,
62	            status: LoanStatus.FULFILLED
63	        });
64	
65	        if (s.s_positionActiveLoanIds[_request.positionId].length >= Constants.MAX_ACTIVE_LOANS_PER_POSITION) {
66	            revert TOO_MANY_ACTIVE_LOANS(_request.positionId);
67	        }
68	
69	        uint256 _loanId = ++s.s_nextLoanId;
70	        s.s_loans[_loanId] = _loan;
71	        s.s_positionActiveLoanIds[_request.positionId].push(_loanId);
72	        // Record the immutable principal + origination timestamp, mirroring
73	        // `_takeLoan`. Without these, `s_loanStartTime[_loanId] == 0` and
74	        // `_outstandingBalance` falls back to the resettable `_loan.startTimestamp`,
75	        // so a partial repayment could move maturity / the penalty clock for a
76	        // request-borrow loan — the #6 fix would not cover this path.
77	        s.s_loanPrincipal[_loanId] = _request.amount;
78	        s.s_loanStartTime[_loanId] = block.timestamp;
79	
80	        s._updateVaultBorrows(_loan.token, _loan.principal);
81	
82	        TokenVault _vault = s.i_tokenVault[_loan.token];
