30	        }
31	    }

1	function _repayLoanFor(LibAppStorage.StorageLayout storage s, uint256 _positionId, uint256 _loanId, uint256 _amount)
2	        internal
3	        returns (uint256)
4	    {
5	        _callerWhitelisted(s);
6	        Loan storage _loan = s.s_loans[_loanId];
7	        if (_loan.positionId != _positionId) revert NOT_LOAN_OWNER(_positionId);
8	        if (_loan.status != LoanStatus.FULFILLED) revert INACTIVE_LOAN();
9	
10	        uint256 _loanDebt = _outstandingBalance(s, _loanId, block.timestamp);
11	        if (_loanDebt == 0) revert NO_OUTSTANDING_DEBT(_positionId, _loan.token);
12	
13	        _allowanceAndBalanceCheck(_loan.token, _amount);
14	
15	        if (_amount > _loanDebt) {
16	            _amount = _loanDebt;
17	        }
18	
19	        uint256 _oldPrincipal = _loan.principal;
20	
21	        // interest-first allocation: cover interest + penalty before any principal,
22	        // and reduce principal by the principal portion ONLY — never fold interest
23	        // into principal (which would re-accrue as compound interest: #12).
24	        uint256 _interestDue = _loanDebt - _oldPrincipal;
25	
26	        // A repayment must at least cover the accrued interest + penalty. This
27	        // stops a dust repayment from resetting the interest anchor (escaping
28	        // accrued interest) — the maturity/penalty clock is already pinned to the
29	        // immutable origination time, so neither can be reset by a token payment (#6).
30	        if (_amount < _interestDue) revert REPAYMENT_BELOW_INTEREST(_amount, _interestDue);
31	
32	        uint256 _principalRepaid = _amount - _interestDue;
33	
34	        _loan.repaid += _amount;
35	        _loan.principal = _oldPrincipal - _principalRepaid;
36	        _loan.startTimestamp = block.timestamp;
37	
38	        // If fully repaid, update loan status and move to closed loans
39	        if (_loan.principal == 0) {
40	            _loan.status = LoanStatus.REPAID;
41	            _removeLoanFromActive(s, _positionId, _loanId);
42	            s.s_positionClosedLoanIds[_positionId].push(_loanId);
43	        }
44	
45	        TokenVault _vault = s.i_tokenVault[_loan.token];
46	        // Book debt/vault accounting against what the vault ACTUALLY received. A
47	        // fee-on-transfer token delivers less than the nominal `_amount`, so
48	        // reducing debt by `_amount` would credit the borrower more than the LPs
49	        // received (#6). Fail closed if the vault is short-changed.
50	        uint256 _before = IERC20(_loan.token).balanceOf(address(_vault));
51	        IERC20(_loan.token).safeTransferFrom(msg.sender, address(_vault), _amount);
52	        uint256 _received = IERC20(_loan.token).balanceOf(address(_vault)) - _before;
53	        if (_received != _amount) revert AMOUNT_MISMATCH(_received, _amount);
54	
55	        s._updateVaultRepays(_loan.token, _principalRepaid);
56	        _vault.repayFixed(_principalRepaid, _amount - _principalRepaid, _loan.annualRateBps);
57	
58	        emit LoanRepayment(_positionId, _loanId, _loan.token, _amount);
59	        return _loan.principal;
60	    }

