1	function _borrow(LibAppStorage.StorageLayout storage s, address _token, uint256 _amount)
2	        internal
3	        returns (uint256)
4	    {
5	        uint256 _positionId = _positionIdCheck(s);
6	        if (!s.s_supportedToken[_token]) revert TOKEN_NOT_SUPPORTED(_token);
7	        if (!s._validateVaultUtlization(_token, _amount)) revert TOKEN_OVERUTILIZATION();
8	
9	        (, uint256 _currentBorrowValue) = s._getTokenValueInUSD(_token, _amount);
10	        uint256 _healthFactor = _getHealthFactor(s, _positionId, _currentBorrowValue);
11	
12	        if (_healthFactor < Constants.MIN_HEALTH_FACTOR) revert HEALTH_FACTOR_TOO_LOW(_healthFactor);
13	
14	        uint256 _tokenBorrow = s.s_positionBorrowed[_positionId][_token];
15	        if (_tokenBorrow == 0) {
16	            s.s_positionBorrowed[_positionId][_token] += _amount;
17	        } else {
18	            s.s_positionBorrowed[_positionId][_token] = _calculateUserDebt(s, _positionId, _token, _amount);
19	        }
20	
21	        s.s_positionBorrowedLastUpdate[_positionId][_token] = block.timestamp;
22	
23	        // Track principal separately and raise the borrow tally by principal only
24	        // (NOT capitalized interest), so it can be decremented symmetrically by
25	        // principal on repay. This keeps config.totalBorrows == outstanding
26	        // principal, which utilization / the borrow cap / interest pricing read.
27	        s.s_positionPrincipal[_positionId][_token] += _amount;
28	        s._updateVaultBorrows(_token, _amount);
29	
30	        TokenVault _vault = s.i_tokenVault[_token];
31	        _vault.borrow(msg.sender, _amount);
32	
33	        emit BorrowComplete(_positionId, _token, _amount);
34	        return s.s_positionBorrowed[_positionId][_token];
35	    }

1	function _repay(LibAppStorage.StorageLayout storage s, address _token, uint256 _amount) internal returns (uint256) {
2	        uint256 _positionId = _positionIdCheck(s);
3	
4	        uint256 _debt = _calculateUserDebt(s, _positionId, _token, 0);
5	        if (_debt == 0) revert NO_OUTSTANDING_DEBT(_positionId, _token);
6	
7	        _allowanceAndBalanceCheck(_token, _amount);
8	
9	        if (_amount > _debt) {
10	            _amount = _debt;
11	        }
12	
13	        RepayStateChangeParams memory _params =
14	            RepayStateChangeParams({positionId: _positionId, token: _token, amount: _amount});
15	        uint256 _principalRepaid = _repayStateChanges(s, _params);
16	        TokenVault _vault = s.i_tokenVault[_token];
17	
18	        // Book against the amount actually received (fee-on-transfer safe, #6).
19	        uint256 _before = IERC20(_token).balanceOf(address(_vault));
20	        IERC20(_token).safeTransferFrom(msg.sender, address(_vault), _amount);
21	        uint256 _received = IERC20(_token).balanceOf(address(_vault)) - _before;
22	        if (_received != _amount) revert AMOUNT_MISMATCH(_received, _amount);
23	        _vault.repay(_principalRepaid, _amount - _principalRepaid);
24	
25	        emit Repay(_positionId, _token, _amount);
26	        return _calculateUserDebt(s, _positionId, _token, 0);
27	    }

1	function _repayStateChanges(LibAppStorage.StorageLayout storage s, RepayStateChangeParams memory _params)
2	        internal
3	        returns (uint256 _principalRepaid)
4	    {
5	        uint256 _totalDebt = _calculateUserDebt(s, _params.positionId, _params.token, 0);
6	        s.s_positionBorrowed[_params.positionId][_params.token] = _totalDebt - _params.amount;
7	        s.s_positionBorrowedLastUpdate[_params.positionId][_params.token] = block.timestamp;
8	
9	        // Interest-first allocation (mirrors `_repayLoanFor` / `_liquidateLoan`):
10	        // a repayment covers accrued interest before any principal. Reducing
11	        // principal first (the old behaviour) let an interest-only repayment
12	        // shrink the principal tally while interest went uncollected —
13	        // understating `totalBorrows` / utilization and mis-splitting the vault's
14	        // principal/interest booking so LP interest leaks to borrowers (#4).
15	        uint256 _principalOutstanding = s.s_positionPrincipal[_params.positionId][_params.token];
16	        uint256 _interestDue = _totalDebt > _principalOutstanding ? _totalDebt - _principalOutstanding : 0;
17	        _principalRepaid = _params.amount > _interestDue
18	            ? (_params.amount - _interestDue > _principalOutstanding ? _principalOutstanding : _params.amount - _interestDue)
19	            : 0;
20	        s.s_positionPrincipal[_params.positionId][_params.token] = _principalOutstanding - _principalRepaid;
21	        s._updateVaultRepays(_params.token, _principalRepaid);
22	    }

