1	function _removeCollateralToken(LibAppStorage.StorageLayout storage s, address _token) internal {
2	        if (_token == address(0)) revert ADDRESS_ZERO();
3	        if (!s.s_supportedCollateralTokens[_token]) revert TOKEN_NOT_SUPPORTED_AS_COLLATERAL(_token);
4	        // Refuse to delist while positions still hold this collateral. Removing it
5	        // from `s_allCollateralTokens` makes the valuation loops count outstanding
6	        // holdings as zero USD, dropping solvent positions below the liquidation
7	        // threshold and letting public liquidators seize the (still price-fed)
8	        // collateral. Users must exit the token first.
9	        if (s.s_totalCollateralDeposited[_token] != 0) revert COLLATERAL_STILL_IN_USE(_token);
10	
11	        s.s_supportedCollateralTokens[_token] = false;
12	        // delete s.s_tokenPriceFeed[_token];
13	
14	        // remove from array
15	        uint256 length = s.s_allCollateralTokens.length;
16	        for (uint256 i = 0; i < length; i++) {
17	            if (s.s_allCollateralTokens[i] == _token) {
18	                s.s_allCollateralTokens[i] = s.s_allCollateralTokens[length - 1];
19	                s.s_allCollateralTokens.pop();
20	                break;
21	            }
22	        }
23	
24	        emit CollateralTokenRemoved(_token);
25	    }

