1	function _calculateUserDebt(
2	        LibAppStorage.StorageLayout storage s,
3	        uint256 _positionId,
4	        address _token,
5	        uint256 _amount
6	    ) internal view returns (uint256 debt) {
7	        uint256 _tokenBorrows = s.s_positionBorrowed[_positionId][_token];
8	
9	        uint256 _from = s.s_positionBorrowedLastUpdate[_positionId][_token];
10	        uint256 _timeElapsed = block.timestamp - _from;
11	
12	        // Fixed APR (#11): price interest at the protocol-set rate over the actual
13	        // elapsed time. Pricing off live utilization let a same-block utilization
14	        // spike retroactively reprice a borrower's whole interval and force a
15	        // wrongful liquidation; the fixed rate removes that manipulable input and
16	        // keeps borrower debt coupled to the vault's (same-rate) LP accrual.
17	        uint256 interestRate = s.s_interestRate;
18	        uint256 factor = ((interestRate * _timeElapsed) * 1e18) / (10000 * 365 days);
19	        debt = _amount + _tokenBorrows + ((_tokenBorrows * factor) / 1e18);
20	
21	        return debt;
22	    }

