1	function _outstandingBalance(Loan memory _loan, uint256 _originationTime, uint256 _timestamp)
2	        internal
3	        pure
4	        returns (uint256)
5	    {
6	        if (_loan.status != LoanStatus.FULFILLED) return 0;
7	
8	        uint256 _maturity = _originationTime + _loan.tenureSeconds;
9	
10	        // Base interest accrues from the (resettable) interest anchor up to
11	        // maturity — never past it, regardless of how many times it is reset.
12	        uint256 _interestEnd = _timestamp < _maturity ? _timestamp : _maturity;
13	        uint256 _interestElapsed = _interestEnd > _loan.startTimestamp ? _interestEnd - _loan.startTimestamp : 0;
14	
15	        uint256 _interest = (_loan.principal * _loan.annualRateBps * _interestElapsed)
16	            / (Constants.BASIS_POINTS_SCALE_256 * Constants.ONE_YEAR);
17	        uint256 _totalOwed = _loan.principal + _interest;
18	
19	        // Penalty accrues against the fixed maturity, not the moving anchor.
20	        if (_timestamp > _maturity) {
21	            uint256 penaltyTime = _timestamp - _maturity;
22	            uint256 penalty = (_totalOwed * (uint256(_loan.annualRateBps) + _loan.penaltyRateBps) * penaltyTime)
23	                / (Constants.BASIS_POINTS_SCALE_256 * Constants.ONE_YEAR);
24	            _totalOwed += penalty;
25	        }
26	
27	        return _totalOwed;
28	    }

