1	function _deposit(LibAppStorage.StorageLayout storage s, address _from, address _token, uint256 _amount)
2	        internal
3	        returns (uint256 shares)
4	    {
5	        if (_token == address(0)) revert ADDRESS_ZERO();
6	        if (_amount == 0) revert AMOUNT_ZERO();
7	        if (!s.s_supportedToken[_token]) revert TOKEN_NOT_SUPPORTED(_token);
8	        uint256 _positionId = s._getPositionIdForUser(_from);
9	        if (_positionId == 0) {
10	            _positionId = s._createPositionFor(_from);
11	        }
12	        TokenVault _tokenVault = s.i_tokenVault[_token];
13	        if (address(_tokenVault) == address(0)) revert TOKEN_NOT_SUPPORTED(_token);
14	
15	        VaultConfiguration storage _config = s.s_tokenVaultConfig[_token];
16	
17	        // SafeERC20 + balance-diff: credit the amount ACTUALLY received, and use
18	        // a transfer that tolerates no-bool-return tokens (e.g. USDT). Raw
19	        // `transferFrom` reverts on those (#13), and crediting the nominal amount
20	        // over-counts fee-on-transfer tokens against real liquidity.
21	        IERC20 _tokenI = IERC20(_token);
22	        uint256 _before = _tokenI.balanceOf(address(this));
23	        _tokenI.safeTransferFrom(_from, address(this), _amount);
24	        uint256 _received = _tokenI.balanceOf(address(this)) - _before;
25	
26	        _config.totalDeposits += _received;
27	
28	        _tokenI.forceApprove(address(_tokenVault), _received);
29	        shares = _tokenVault.deposit(_received, _from);
30	
31	        emit Deposit(_positionId, _token, _received);
32	    }

1	function _withdraw(LibAppStorage.StorageLayout storage s, address _to, address _token, uint256 _amount) internal {
2	        if (_token == address(0)) revert ADDRESS_ZERO();
3	        if (_amount == 0) revert AMOUNT_ZERO();
4	        if (!s.s_supportedToken[_token]) revert TOKEN_NOT_SUPPORTED(_token);
5	
6	        uint256 _positionId = s._getPositionIdForUser(_to);
7	        if (_positionId == 0) revert NO_POSITION_ID(_to);
8	
9	        TokenVault _tokenVault = s.i_tokenVault[_token];
10	        if (address(_tokenVault) == address(0)) revert TOKEN_NOT_SUPPORTED(_token);
11	
12	        VaultConfiguration storage _config = s.s_tokenVaultConfig[_token];
13	
14	        // Snapshot share supply and the deposit base BEFORE the burn so the
15	        // principal portion of this withdrawal can be derived proportionally.
16	        uint256 _supplyBefore = _tokenVault.totalSupply();
17	        uint256 _depositsBefore = _config.totalDeposits;
18	
19	        uint256 _shares = _tokenVault.withdraw(_amount, _to, msg.sender);
20	
21	        // Decrement the deposit base by the PRINCIPAL portion only — proportional
22	        // to the shares burned, not the interest-inclusive asset amount paid out.
23	        // Subtracting the full `_amount` (principal + earned interest) drifts the
24	        // counter below the real supplied principal and clamps it to 0, which
25	        // forces utilization to 100% and DoSes new borrows (#8).
26	        uint256 _principalOut = _supplyBefore == 0 ? 0 : (_depositsBefore * _shares) / _supplyBefore;
27	        if (_principalOut > _config.totalDeposits) {
28	            _config.totalDeposits = 0;
29	        } else {
30	            _config.totalDeposits -= _principalOut;
31	        }
32	
33	        emit Withdrawal(_positionId, _token, _amount);
34	    }

1	function _upgradeVault(LibAppStorage.StorageLayout storage s, address _token, VaultConfiguration memory _config)
