4	    {
5	        TokenVault _oldVault = s.i_tokenVault[_token];
6	        if (address(_oldVault) == address(0)) {
7	            revert TOKEN_NOT_SUPPORTED(_token);
8	        }
9	
10	        // Swapping the vault contract does not migrate its assets, LP shares, or
11	        // outstanding borrows (#10) — doing so with value present permanently
12	        // strands every depositor. Only allow the swap while the vault is empty
13	        // (pre-launch or after a full drain); routine config changes use the
14	        // dedicated in-place setters instead.
