16	        uint256 _outstandingBorrows = s.s_tokenVaultConfig[_token].totalBorrows;
17	        if (_outstandingShares != 0 || _outstandingBorrows != 0) {
18	            revert VAULT_NOT_EMPTY(_outstandingShares, _outstandingBorrows);
19	        }
20	
21	        TokenVault _tokenVault =
22	            new TokenVault(_token, _oldVault.name(), _oldVault.symbol(), address(this), s.s_interestRate, _config.reserveFactor);
23	        s.i_tokenVault[_token] = _tokenVault;
24	
25	        s.s_tokenVaultConfig[_token] = VaultConfiguration({
26	            totalDeposits: 0,
27	            totalBorrows: 0,
28	            reserveFactor: _config.reserveFactor,
29	            baseRate: _config.baseRate,
30	            slopeRate: _config.slopeRate,
31	            optimalUtilization: _config.optimalUtilization,
32	            liquidationBonus: _config.liquidationBonus,
33	            lastUpdated: block.timestamp
34	        });
