27	            _withdraw(_token, _config, _toWithdraw);
28	            _position.principal -= _toWithdraw;
29	            _config.totalPrincipal -= _toWithdraw;
30	
31	            emit YieldReleased(_positionId, _token, _toWithdraw);
32	        }
33	    }

