1	function _pendingYield(LibAppStorage.StorageLayout storage s, uint256 _positionId, address _token)
2	        internal
3	        view
4	        returns (uint256)
5	    {
6	        YieldStrategyConfig storage _config = s.s_yieldConfigs[_token];
7	        if (!_config.enabled || _config.totalPrincipal == 0) {
8	            return s.s_positionYield[_positionId][_token].userAccrued;
9	        }
10	
11	        uint256 _currentBalance = _config.aToken == address(0) ? 0 : IERC20(_config.aToken).balanceOf(address(this));
12	        uint256 _accrued = 0;
13	        if (_currentBalance > _config.lastRecordedBalance) {
14	            uint256 _protocolShare = ((_currentBalance - _config.lastRecordedBalance) * _config.protocolShareBps)
15	                / Constants.BASIS_POINTS_SCALE;
16	            uint256 _userShare = (_currentBalance - _config.lastRecordedBalance) - _protocolShare;
17	            _accrued = _userShare;
18	        }
19	
20	        uint256 _accYield = _config.accYieldPerPrincipalRay;
21	        if (_accrued > 0) {
22	            _accYield += (_accrued * RAY) / _config.totalPrincipal;
23	        }
24	
25	        YieldPosition storage _position = s.s_positionYield[_positionId][_token];
26	        if (_accYield <= _position.entryAccYieldPerPrincipalRay) {
27	            return _position.userAccrued;
28	        }
29	        uint256 _delta = _accYield - _position.entryAccYieldPerPrincipalRay;
30	        return _position.userAccrued + ((_position.principal * _delta) / RAY);
31	    }

1	function _accrueYield(LibAppStorage.StorageLayout storage s, address _token) internal {
2	        YieldStrategyConfig storage _config = s.s_yieldConfigs[_token];
3	        if (!_shouldProcess(_config, _token) || _config.totalPrincipal == 0) {
4	            _refreshRecordedBalance(_config);
5	            return;
6	        }
7	
8	        uint256 _currentBalance = IERC20(_config.aToken).balanceOf(address(this));
9	        if (_currentBalance <= _config.lastRecordedBalance) {
10	            _config.lastRecordedBalance = _currentBalance;
11	            return;
12	        }
13	
14	        uint256 _accrued = _currentBalance - _config.lastRecordedBalance;
15	        uint256 _protocolShare = (_accrued * _config.protocolShareBps) / Constants.BASIS_POINTS_SCALE;
16	        uint256 _userShare = _accrued - _protocolShare;
17	
18	        _config.accYieldPerPrincipalRay += (_userShare * RAY) / _config.totalPrincipal;
19	        _config.protocolAccrued += _protocolShare;
20	        _config.lastRecordedBalance = _currentBalance;
21	
22	        emit YieldAccrued(_token, _userShare, _protocolShare);
23	    }

1	function _settlePositionYield(YieldStrategyConfig storage _config, YieldPosition storage _position) private {
