4	            return;
5	        }
6	
7	        uint256 _delta = _config.accYieldPerPrincipalRay - _position.entryAccYieldPerPrincipalRay;
8	        if (_delta == 0) return;
9	
10	        uint256 _pending = (_position.principal * _delta) / RAY;
11	        _position.userAccrued += _pending;
12	        _position.entryAccYieldPerPrincipalRay = _config.accYieldPerPrincipalRay;
13	    }

1	function _supply(address _token, YieldStrategyConfig storage _config, uint256 _amount) private {
2	        if (_amount == 0) return;
3	
4	        IERC20(_token).forceApprove(_config.aavePool, _amount);
5	        IAavePool(_config.aavePool).supply(_token, _amount, address(this), 0);
