1	function _rebalanceForWithdrawal(
2	        LibAppStorage.StorageLayout storage s,
3	        uint256 _positionId,
4	        address _token,
5	        uint256 _withdrawAmount
6	    ) internal {
7	        if (_withdrawAmount == 0) {
8	            _rebalancePosition(s, _positionId, _token);
9	            return;
10	        }
11	
12	        YieldStrategyConfig storage _config = s.s_yieldConfigs[_token];
13	        if (!_shouldProcess(_config, _token)) return;
14	
15	        _accrueYield(s, _token);
16	        YieldPosition storage _position = s.s_positionYield[_positionId][_token];
17	        _settlePositionYield(_config, _position);
18	
19	        uint256 _collateral = s.s_positionCollateral[_positionId][_token];
20	        uint256 _target = (_collateral * _config.allocationBps) / Constants.BASIS_POINTS_SCALE;
21	
22	        uint256 _targetWithdraw = 0;
23	        if (_position.principal > _target) {
24	            _targetWithdraw = _position.principal - _target;
25	        }
26	
27	        uint256 _balance = IERC20(_token).balanceOf(address(this));
28	        uint256 _deficitWithdraw = 0;
29	        if (_balance < _withdrawAmount) {
30	            _deficitWithdraw = _withdrawAmount - _balance;
31	        }
32	
33	        uint256 _toWithdraw = _targetWithdraw > _deficitWithdraw ? _targetWithdraw : _deficitWithdraw;
34	
35	        if (_toWithdraw > 0) {
36	            if (_toWithdraw > _position.principal) revert YIELD_LIQUIDITY_DEFICIT(_token, _toWithdraw);
37	
38	            _withdraw(_token, _config, _toWithdraw);
39	            _position.principal -= _toWithdraw;
40	            _config.totalPrincipal -= _toWithdraw;
41	
42	            emit YieldReleased(_positionId, _token, _toWithdraw);
43	        }
44	
45	        if (_target > _position.principal) {
46	            uint256 _toAllocate = _target - _position.principal;
47	            uint256 _newBalance = _toWithdraw > 0 ? _balance + _toWithdraw : _balance;
48	
49	            uint256 _availableToSupply = 0;
50	            if (_newBalance > _withdrawAmount) {
51	                _availableToSupply = _newBalance - _withdrawAmount;
52	            }
53	
54	            if (_toAllocate > _availableToSupply) {
55	                _toAllocate = _availableToSupply;
56	            }
57	
58	            if (_toAllocate > 0) {
59	                _supply(_token, _config, _toAllocate);
60	                _position.principal += _toAllocate;
61	                _config.totalPrincipal += _toAllocate;
62	
63	                emit YieldAllocated(_positionId, _token, _toAllocate);
64	            }
65	        }
66	    }

1	function _refreshRecordedBalance(YieldStrategyConfig storage _config) private {
